/**
 * Legt den Umschlag an. Ab hier reisen alle Stufen mit demselben Objekt und
 * füllen nur ihren eigenen Platz - Vorbild ist das Muster aus der Vorlage
 * workflow_20_normalize_summarize.
 *
 * Alles Mandantenspezifische steht im Baustein davor, nicht hier im Code.
 * Damit ist ein zweiter Mandant ein Konfigurationssatz und kein zweiter Workflow.
 *
 * liefermodus (seit 12.10.2026): 'test' ist der Standard. Nur bei 'echt'
 * legt BC3-80 nach einer Freigabe Zweig und Pull Request im Gruppen-Repository
 * an. Umgestellt wird ausschliesslich in "Lauf einstellen".
 */
const cfg = $input.first().json;

return [{
  json: {
    lauf_id: `bc3-${$execution.id}`, // ab BC3-40 die lieferung_id
    umschlag: {
      lauf: {
        lauf_nr: `bc3-${$execution.id}`, // Schlüssel für BC3-91 und laeufe
        pfad: cfg.pfad,
        mandant: cfg.mandant,
        ablage: cfg.ablage,
        ablage_ordner: cfg.ablage_ordner || null,
        gestartet_am: cfg.gestartet_am,
        gestartet_von: cfg.gestartet_von,
        bemerkung: cfg.bemerkung || null,
        liefermodus: cfg.liefermodus === 'echt' ? 'echt' : 'test',
      },
      quelle: {},
      konzept: {},
      potenziale: [],
      epics: [],
      protokoll: [{
        stufe: 'BC3-00 Orchestrator',
        zeitpunkt: new Date().toISOString(),
        status: 'gestartet',
        befunde: [],
      }],
    },
  },
}];

// Fasst den Lauf zusammen, Grundlage für den Abschlussbericht und die Zeile in laeufe.
// Hier kommen zwei Wege an: der fertige Lauf nach BC3-80 und der abgebrochene aus "Fehler einordnen".
const rein = $input.first().json;
const u = rein.umschlag || {};
const prot = u.protokoll || [];
const offen = prot.filter(p => p.status === 'offen');
const abgebrochen = prot.filter(p => p.status === 'abgebrochen');
const befunde = prot.flatMap(p => (p.befunde || []).map(b => ({ stufe: p.stufe, befund: b })));

// "ok" nur, wenn wirklich geliefert und an Gate 2 entschieden wurde.
const fehlt = [];
if (!(u.lieferung?.dateien || []).length) fehlt.push('keine Dateien in der Lieferung');
if (!u.gate2?.entscheidung) fehlt.push('keine Entscheidung an Gate 2');
const vollstaendig = abgebrochen.length === 0 && u.lauf_status !== 'unvollständig' && fehlt.length === 0;
const abgelegt = (u.lieferung?.abgelegt || []).length;

return [{
  json: {
    // Laufnummer für den Bericht, ab BC3-40 trägt rein.lauf_id die lieferung_id
    lauf_id: u.lauf?.lauf_nr || rein.lauf_id,
    lieferung_id: u.lieferung?.lieferung_id || null,
    status: vollstaendig ? 'ok' : 'unvollständig',
    stufen: prot.length,
    offen: offen.map(p => p.stufe),
    abgebrochen: abgebrochen.map(p => p.stufe.replace(/ \(abgebrochen\)$/, '')),
    fehlt,
    dateien_abgelegt: abgelegt,
    befunde,
    stoerfall: u.stoerfall || null,
    gate2: u.gate2 || null,
    naechster_schritt: !vollstaendig
      ? (u.stoerfall?.was_tun
          || (abgebrochen.length === 0 && fehlt.length ? `Umschlag unvollständig: ${fehlt.join(', ')}.` : '')
          || 'In der Ausführungsansicht nachsehen, dann erneut starten.')
      : u.gate2?.entscheidung === 'approved'
        ? (u.gate2?.pr
            ? (u.gate2.pr.gemergt
                ? `Fertig. Pull Request #${u.gate2.pr.nummer} zusammengeführt, BC4 holt aus main.`
                : `Pull Request #${u.gate2.pr.nummer} ist offen, von Hand zusammenführen.`)
            : u.gate2?.liefermodus === 'test'
              ? 'Testlauf freigegeben, kein Pull Request (Modus test).'
              : 'Freigegeben, aber kein Pull Request entstanden. Protokoll von BC3-80 ansehen.')
        : u.gate2?.entscheidung === 'nachbessern'
          ? 'Zur Nachbesserung zurückgegeben. Nach der Nachbesserung neu starten.'
        : u.gate2?.entscheidung === 'rejected'
          ? 'An Gate 2 abgelehnt. Die Dateien bleiben in _vorschau, BC4 sieht nichts.'
          : 'BC3-80 Gate 2 starten',
    protokoll: prot,
    umschlag: u,
  },
}];

/**
 * R6 - einmalige Wiederholung nach einem Abbruch in BC3-40.
 *
 * Der Aufruf von BC3-40 steht auf "Fehlerausgang weiterleiten". Landet der Lauf
 * hier, hat eine der Prüfstellen abgebrochen. Beim ersten Mal wird BC3-20 mit
 * verschärftem Auftrag wiederholt, beim zweiten Mal ist Schluss.
 *
 * Seit 12.10.2026 reist die Meldung im Plan mit (plan.r6_fehler), damit der
 * zweite Durchgang von BC3-20 weiss, WORAN der erste gescheitert ist. Vorher
 * bekam er nur einen festen Text. Die Meldung ist seit demselben Tag einzeilig
 * (BC3-40 'Lieferung pruefen'), sonst kam hier nur die Kopfzeile an.
 */
const rein = $input.first().json;
const u = rein.umschlag || $('BC3-15 Plan festlegen').first().json.umschlag || {};
const plan = u.plan || { wiederholungen: 0, modi: {} };
const meldung = rein.error?.message || rein.message || 'ohne Angabe';
// n8n haengt an Fehler aus Code-Bausteinen " [line N]" an - fuer den Auftrag
// an das Modell ist das Rauschen.
const kern = String(meldung).split('\n')[0].replace(/\s*\[line \d+\]\s*$/, '').slice(0, 1500);

// Beim zweiten Mal NICHT mehr werfen - sonst stirbt der Lauf und die
// Arbeit davor ist verloren. Stattdessen den Bescheid weitergeben; die
// Verzweigung dahinter schickt es in die Störfall-Behandlung.
if ((plan.wiederholungen || 0) >= 1) {
  return [{ json: { lauf_id: rein.lauf_id, wiederholen: false, umschlag: u,
    error: { message: 'BC3-40 ist zum zweiten Mal abgebrochen: ' + kern } } }];
}

return [{
  json: {
    lauf_id: rein.lauf_id,
    wiederholen: true,
    umschlag: {
      ...u,
      plan: {
        ...plan,
        wiederholungen: (plan.wiederholungen || 0) + 1,
        modi: { ...plan.modi, 'BC3-20': 'streng' },
        r6_fehler: kern,
      },
      protokoll: [...(u.protokoll || []), {
        stufe: 'BC3-00 Wiederholung (R6)',
        zeitpunkt: new Date().toISOString(),
        status: 'wiederholung',
        befunde: ['BC3-40 abgebrochen: ' + kern,
                  'BC3-20 wird einmal mit verschärftem Auftrag wiederholt, die Meldung geht mit'],
      }],
    },
  },
}];

/**
 * Ein Schritt hat abgebrochen. Dieser Baustein stellt fest, welcher, und rettet
 * den Umschlag, damit die Arbeit davor nicht verloren ist.
 *
 * Der Fehlerausgang eines Aufrufs enthält keine Daten, nur die Meldung. Der Umschlag
 * kommt deshalb vom letzten Schritt, der noch einen geliefert hat. Gescheitert ist der
 * letzte Schritt, der überhaupt gelaufen ist, n8n arbeitet die Kette der Reihe nach ab.
 */
// Namen der Aufruf-Bausteine in diesem Workflow, bei jeder Umbenennung mitziehen
const STUFEN = ["BC3-10 Konzept einlesen", "BC3-15 Plan festlegen", "BC3-20 Stories schneiden", "BC3-30 Compliance prüfen", "BC3-40 Tickets bauen und prüfen", "BC3-50 Architektur", "BC3-70 Ausliefern", "BC3-80 Gate 2"];

const gelaufen = (name) => { try { return $(name).isExecuted; } catch (e) { return false; } };
const umschlagVon = (name) => {
  try {
    const j = $(name).first().json;
    return j && j.umschlag ? j.umschlag : null;
  } catch (e) { return null; }
};

let gescheitert = null;
for (const s of STUFEN) if (gelaufen(s)) gescheitert = s;

let umschlag = null;
const bis = gescheitert ? STUFEN.indexOf(gescheitert) : STUFEN.length;
for (let i = bis - 1; i >= 0 && !umschlag; i--) umschlag = umschlagVon(STUFEN[i]);
for (const fallback of ['BC3-15 Plan festlegen', 'Laufprotokoll: Start', 'Umschlag anlegen']) {
  if (!umschlag) umschlag = umschlagVon(fallback);
}
umschlag = umschlag || {};

// Die Meldung kommt je nach Baustein in unterschiedlicher Gestalt.
const rein = $input.first().json;
const f = (rein.error && typeof rein.error === 'object') ? rein.error : {};
const meldung = String(
  f.message || rein.message ||
  (typeof rein.error === 'string' ? rein.error : '') || 'ohne Angabe'
).split('\n')[0].slice(0, 400);

let lauf_id = null;
for (const n of ['Umschlag anlegen', 'Lauf einstellen']) {
  try { lauf_id = lauf_id || $(n).first().json.lauf_id; } catch (e) { /* egal */ }
}

const stoerfall = {
  stufe: gescheitert || 'unbekannt',
  baustein: f.node?.name || null,
  baustein_typ: f.node?.type || null,
  meldung,
  unter_ausfuehrung: f.executionId || null,
  wiederholungen: umschlag.plan?.wiederholungen || 0,
  erreicht: (umschlag.protokoll || []).map(x => x.stufe),
};

return [{ json: { lauf_id: lauf_id || umschlag.lauf?.lauf_nr || 'unbekannt', umschlag, stoerfall } }];

/**
 * Wie geht es weiter? Das entscheiden REGELN, nicht der Agent.
 *
 * Der Agent hat davor erklärt, was vermutlich los ist, und darf vorschlagen.
 * Übernommen wird sein Vorschlag nur dort, wo die Regel es zulässt - genau
 * wie bei "Hinweise übernehmen" nach dem Auffälligkeits-Agenten.
 *
 * Ein dynamischer Wiedereintritt in eine bestimmte Stufe ist in n8n nicht
 * ausdrückbar; die Verdrahtung ist fest. Die Wiederholung bleibt deshalb eine
 * Empfehlung an den Menschen - ausser bei R6, das eigens verdrahtet ist.
 */
const d = $('Stufe gescheitert').first().json;
const s = d.stoerfall;

// Bis zum 06.09.2026 stand hier der Agent „Stoerfall erklaeren“. Er ist
// entfallen: die sieben Regelmuster unten gewinnen ohnehin immer
// (treffer?.tun || ...), und im einzigen Fall, fuer den er gedacht war
// (403 tier_not_allowed, Lauf 69 am 03.09.), waere er selbst mit ausgefallen -
// er lief auf demselben Modell.
// Der Leseversuch bleibt stehen und liefert jetzt immer null. Wer spaeter
// wieder einen Erklaerer davorhaengt, muss hier nichts aendern.
let erklaerung = null;
try {
  const roh = $input.first().json.output ?? $input.first().json.text;
  const sauber = String(roh ?? '').trim()
    .replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  if (sauber) erklaerung = JSON.parse(sauber);
} catch (e) { erklaerung = null; }

// --- Regeltabelle: was ist zu tun ---------------------------------------
// Bewusst hier und nicht im Modell: wer später fragt, warum ein Lauf
// abgebrochen wurde, soll die Regel lesen koennen.
const REGELN = [
  // Vor allen anderen: gesperrter Aufruf eines Kind-Workflows
  { muster: /cannot be called by this workflow|SubworkflowPolicyDenial|is not active/i,
    art: 'Aufruf nicht erlaubt', wiederholen: false,
    tun: 'Der aufgerufene Workflow ist nicht veröffentlicht oder liegt in einem anderen Konto. ' +
         'Ihn veröffentlichen oder ins Konto von BC3-00 holen, dann neu starten.' },
  { muster: /authorization grant|refresh token|invalid_grant|unauthorized|401/i,
    art: 'Zugang', wiederholen: false,
    tun: 'Zugangsdaten in n8n neu anmelden, dann den Lauf erneut starten.' },
  // Vor der allgemeinen 403-Regel, sonst wird der Tarif-Fall als Abrufgrenze
  // gedeutet und jemand wartet vergeblich. Am 03.09.2026 an Lauf 69 passiert:
  // mistral-large-latest war ploetzlich nicht mehr im Tarif enthalten.
  { muster: /tier_not_allowed|not available in your subscription|insufficient.?quota|billing|payment required|402/i,
    art: 'Modell nicht verfügbar', wiederholen: false,
    tun: 'Das Sprachmodell ist im Tarif nicht enthalten oder das Guthaben ist leer. ' +
         'Im Konto des Anbieters nachsehen. Wiederholen hilft nicht.' },
  { muster: /rate limit|429|403/i,
    art: 'Abrufgrenze', wiederholen: true,
    tun: 'Eine Abrufgrenze ist erreicht. Später erneut starten.' },
  // Anbieter kurz nicht erreichbar (Mistral 503 in Lauf 1343)
  { muster: /service unavailable|bad gateway|gateway time-?out|internal server error|overloaded|try again later|\b50[0234]\b/i,
    art: 'Dienst nicht erreichbar', wiederholen: true,
    tun: 'Ein Dienst (meist das Sprachmodell) war kurz nicht erreichbar, am Lauf ist nichts falsch. ' +
         'In ein paar Minuten neu starten.' },
  { muster: /404|not found|nicht erreichbar/i,
    art: 'Quelle nicht erreichbar', wiederholen: false,
    tun: 'Die Quelle ist nicht da. Pfad der Lieferung prüfen.' },
  { muster: /timeout|ETIMEDOUT|socket hang up|ECONNRESET/i,
    art: 'Netzfehler', wiederholen: true,
    tun: 'Eine Verbindung ist abgerissen. Erneut starten.' },
  { muster: /Ausgangspr(ü|ue)fung|schema|Oberste Ebene|Pflichtfeld/i,
    art: 'Eigener Fehler', wiederholen: true,
    tun: 'Die Ausgangsprüfung hat abgebrochen. BC3-20 läuft bei R6 einmal streng nach.' },
  { muster: /kein Aggregat|keine Potenziale|keine tickets|Keine Dateien|nichts geliefert/i,
    art: 'Reihenfolge', wiederholen: false,
    tun: 'Eine Stufe hat nichts geliefert. Zuerst die Stufe davor ansehen.' },
];
const treffer = REGELN.find(r => r.muster.test(s.meldung));

const art = treffer?.art || 'unbekannt';
const wiederholen = treffer ? treffer.wiederholen : false;
const tun = treffer?.tun
  || (erklaerung?.was_tun ? String(erklaerung.was_tun) : 'In der Ausführungsansicht nachsehen.');

// Der Agent darf die Regel NICHT umstossen. Weicht er ab, wird das vermerkt.
const abweichung = (erklaerung && typeof erklaerung.wiederholen_sinnvoll === 'boolean'
                    && erklaerung.wiederholen_sinnvoll !== wiederholen)
  ? `Der Agent hält Wiederholen für ${erklaerung.wiederholen_sinnvoll ? 'sinnvoll' : 'nicht sinnvoll'}, die Regel sagt das Gegenteil. Es gilt die Regel.`
  : null;

const u = d.umschlag || {};
return [{
  json: {
    lauf_id: d.lauf_id,
    umschlag: {
      ...u,
      lauf_status: 'unvollständig',
      stoerfall: {
        ...s, art, wiederholen_laut_regel: wiederholen, was_tun: tun,
        erklaerung: erklaerung || null,
      },
      protokoll: [...(u.protokoll || []), {
        stufe: s.stufe + ' (abgebrochen)',
        zeitpunkt: new Date().toISOString(),
        status: 'abgebrochen',
        befunde: [
          `${s.baustein ? 'Baustein "' + s.baustein + '": ' : ''}${s.meldung}`,
          `Einordnung: ${art}. ${tun}`,
          ...(erklaerung?.ursache_vermutlich ? ['Vermutung des Agenten: ' + erklaerung.ursache_vermutlich] : []),
          ...(erklaerung?.unsere_schuld !== undefined
              ? ['Unsere Schuld: ' + (erklaerung.unsere_schuld ? 'ja' : 'nein, die Umgebung')] : []),
          ...(abweichung ? [abweichung] : []),
          ...(s.unter_ausfuehrung ? ['Die Daten des gescheiterten Kindes liegen in Ausführung '
                                     + s.unter_ausfuehrung + '.'] : []),
        ],
      }],
    },
  },
}];

/**
 * Schreibt den Abschlusssatz des Laufs.
 *
 * Bis zum 06.09.2026 stand davor der Agent „Bericht schreiben“. Er kostete
 * jeden Lauf einen Mistral-Aufruf, sein Auftrag lautete woertlich „fuer einen
 * Menschen, der VOR Gate 2 sitzt“ - und er lief HINTER Gate 2, also fuer
 * jemanden, der schon entschieden hatte. Sein Text landete hier und ging nicht
 * weiter, denn dieser Baustein ist der letzte im Workflow.
 *
 * Der Leseversuch unten bleibt stehen und liefert jetzt immer null; damit
 * greift der Satz aus den Zahlen, der ohnehin schon fertig war. Wer spaeter
 * wieder einen Berichtschreiber davorhaengt, muss hier nichts aendern.
 */
const z = $('Lauf abschliessen').first().json;

let text = null;
try {
  text = String($input.first().json.output ?? $input.first().json.text ?? '').trim() || null;
} catch (e) { text = null; }

if (!text) {
  const n = z.befunde.length;
  const lauf = z.lieferung_id ? `${z.lauf_id} (Lieferung ${z.lieferung_id})` : z.lauf_id;
  text = z.status === 'ok'
    ? `Lauf ${lauf} vollständig: ${z.stufen} Stufen, ${z.dateien_abgelegt} Dateien abgelegt, ${n} Befunde. Nächster Schritt: ${z.naechster_schritt}`
    : `Lauf ${lauf} unvollständig, abgebrochen in ${z.abgebrochen.join(', ') || 'unbekannt'}. ${z.naechster_schritt}`;
}

return [{ json: { ...z, bericht: text } }];

/**
 * Gate 2 vorbereiten: die Maschine prueft, was sie hier noch pruefen KANN.
 *
 * Bis zum 06.09.2026 standen hier neun Pruefpunkte. Die Expertenrunde hat sie
 * einzeln gegen drei Fragen gehalten - besitzt BC3 die Aussage, kann der Punkt
 * an DIESER Stelle noch scheitern, und aendert er etwas? Vier haben bestanden.
 *
 * WEGGEFALLEN, weil sie hier nicht mehr scheitern koennen:
 *   kennung             BC3-10 "Eingang pruefen" wirft, wenn kp_id fehlt oder
 *                       nicht auf ^KP-(0[1-9]|10)$ passt. Was Gate 2 hier prueft,
 *                       kann gar nicht mehr falsch sein - eine Zeile, die immer
 *                       [ok] sagt, erzieht zum Ueberfliegen der anderen.
 *   nachvollziehbarkeit prueft (prot.length && lieferung_id) - beides ist
 *                       gesetzt, sobald der Lauf ueberhaupt bis hierher kommt.
 *                       Selbstauskunft, im Dokument selbst kein Sperrgrund.
 *
 * IN DIE KOPFZEILE GEWANDERT, weil sie Tatsachen sind und keine Haekchen:
 *   vertragstreue       das Urteil faellt BC3-40 "Lieferung pruefen" - es wirft
 *                       bei jedem harten Verstoss, bevor irgendetwas hochgeladen
 *                       wird. Hier steht nur noch, WOGEGEN geprueft wurde.
 *   herkunft            value_quelle ist eine Aussage ueber BC2s Datenhygiene.
 *                       Was ein Mensch braucht, ist die Warnung "diese Zahlen
 *                       sind vorlaeufig" - oben, wo sie die Beurteilung faerbt.
 *
 * ZUSAMMENGELEGT:
 *   architektur         geht in vollstaendigkeit auf - es ist dieselbe Frage:
 *                       ist alles in der Kiste.
 *   compliance          geht in pflichten_zugeordnet auf. Er prueft nur, ob
 *                       BC3-30 durchgelaufen ist; ohne Befund gibt es keine
 *                       Pflichten. Die Widerspruchspruefung laeuft weiter.
 *
 * NEU:
 *   ablage              "Die Lieferung liegt und ist erreichbar". Der
 *                       Formulartext schickt zur Stichprobe in ticket_set.json,
 *                       nannte aber nie einen Ort - und zeigte lauter [ok],
 *                       auch wenn die Ablage am Drive-Zugang gescheitert war.
 *                       Dieser Punkt faellt tatsaechlich, und er ist die
 *                       Vorbedingung dafuer, dass die Stichprobe beantwortbar ist.
 */
const rein = $input.first().json;
const u = rein.umschlag || {};
const dateien = u.lieferung?.dateien || [];
const t = dateien.find(x => x._datei === 'tickets') || {};
const audit = dateien.find(x => String(x._datei || '').startsWith('compliance')) || {};
const alleStories = (t.epics || []).flatMap(e => e.stories || []);

// Drei Merkmale, nicht eines - und die Quelle wird mitgefuehrt. R2 belegt
// keinen Anhang III, sondern einen Wortfund; wer das gleichsetzt, schreibt BC4
// in den Pull Request, Anhang III sei einschlaegig, wo nur ein Wort stand.
const klasseRoh = String(audit.vorpruefung?.ai_act_klasse || audit.ai_act_klasse || '').trim();
const anhangIII = audit.vorpruefung?.anhang_iii_kategorie || audit.anhang_iii_kategorie;
const ausAkte = /^(high|hoch|hochrisiko|unacceptable|unzul(ae|ä)ssig|verboten)$/i
  .test(klasseRoh) || !!anhangIII;
const ausPlan = u.plan?.hochrisiko === true;
const hochrisiko = ausAkte || ausPlan;
const hochrisikoQuelle = ausAkte && ausPlan ? 'Compliance-Akte und Regel R2'
  : ausAkte ? 'Compliance-Akte'
  : ausPlan ? 'Regel R2 (Kernprozess oder Personenbegriff im Konzept) - die Akte '
              + 'sagt es NICHT, das ist kein Beleg für Anhang III'
  : null;

function ja(beleg) { return { ok: true, beleg }; }
function nein(beleg, abhilfe) { return { ok: false, beleg, abhilfe }; }

const PRUEFUNGEN = [
  {
    id: 'vollstaendigkeit', titel: 'Die Lieferung enthält alles Gebaute',
    pruefen: () => {
      const epics = (t.epics || []).length;
      const leer = (t.epics || []).filter(e => !(e.stories || []).length).map(e => e.titel);
      const erwartet = u.aggregat?.anzahl_epics;
      const md = dateien.find(x => x._datei === 'architecture');
      const bp = dateien.find(x => x._datei === 'blueprint');
      if (!epics) return nein('keine Epics in der Lieferung',
        'BC3-20 hat nichts geliefert. Ausführung von BC3-20 ansehen.');
      if (leer.length) return nein(`${epics} Epics, davon ohne Story: ${leer.join('; ')}`,
        'Das betroffene Epic in BC3-20 erneut schneiden lassen.');
      if (erwartet != null && erwartet !== epics)
        return nein(`${epics} Epics geliefert, ${erwartet} erwartet`,
          'Unterwegs sind Epics verloren gegangen. '
          + 'BC3-20 „Vollständigkeit prüfen" ansehen.');
      const fehlt = [!md && 'architecture.md', !bp && 'blueprint.json'].filter(Boolean);
      if (fehlt.length) return nein(
        `${epics} Epics, ${alleStories.length} Stories - aber es fehlt: ${fehlt.join(', ')}`,
        'BC3-50 ansehen.');
      return ja(`${epics} Epics, ${alleStories.length} Stories, keines leer; `
        + `architecture.md (${String(md.inhalt || '').length} Zeichen) und `
        + `blueprint.json mit ${(bp.komponenten || []).length} Komponenten liegen bei`);
    },
  },
  {
    id: 'akzeptanzkriterien', titel: 'Akzeptanzkriterien prüfbar',
    pruefen: () => {
      const ohne = alleStories.filter(s => !(s.akzeptanzkriterien || []).length);
      const ohneMess = alleStories.filter(s =>
        (s.akzeptanzkriterien || []).some(a => !a.messverfahren || /^offen:/i.test(String(a.messverfahren))));
      if (ohne.length) return nein(
        `${ohne.length} von ${alleStories.length} Stories ohne Kriterium: `
        + ohne.slice(0, 3).map(s => s.titel).join('; '),
        'BC3-20 erzeugt sie; fehlen sie, den Story-Architekten für dieses Epic '
        + 'erneut laufen lassen.');
      // Seit 22.10.2026 (Svetlana): fehlende Messverfahren sind kein offener Punkt. Sie kommen
      // so von BC2, BC3 gibt sie unverändert weiter und vermerkt sie in offene-punkte.json.
      // Einen Rückweg zu BC2 gibt es noch nicht (of-17).
      if (ohneMess.length) return ja(
        `alle ${alleStories.length} Stories haben Kriterien; ${ohneMess.length} davon ohne `
        + 'Messverfahren aus dem Konzept, in den offenen Punkten vermerkt');
      return ja(`alle ${alleStories.length} Stories haben Kriterien mit Messverfahren`);
    },
  },
  {
    id: 'pflichten_zugeordnet', titel: 'Rechtliche Einordnung und Zuordnung',
    pruefen: () => {
      const a = audit.vorpruefung || audit;
      if (!a.ampel || !a.ai_act_klasse)
        return nein('kein Compliance-Befund in der Lieferung',
          'BC3-30 ist nicht durchgelaufen. Ausführung ansehen.');
      // Widerspruch in sich: eine Anhang-III-Kategorie gibt es nur bei
      // Hochrisiko. Der Slicer entscheidet in die sichere Richtung - und sagt
      // es, statt es zu verschlucken.
      if (anhangIII && !/^(high|hoch|hochrisiko|unacceptable)$/i.test(klasseRoh))
        return nein(
          `Ampel ${a.ampel}, Klasse "${klasseRoh}" - aber Anhang III genannt: `
          + `${anhangIII}. Das widerspricht sich.`,
          'Eine Anhang-III-Kategorie gibt es nur bei Hochrisiko. Der Slicer '
          + 'behandelt die Lieferung deshalb als Hochrisiko. Im Compliance-Befund '
          + 'von BC3-30 nachsehen, welches der beiden Felder falsch ist.');
      const p = audit.pflichten || [];
      const ohne = p.filter(x => !x.adressat);
      const g = audit.pflichten_nach_adressat || {};
      const ohneStory = (audit.pflichten_ohne_story || []).length;
      if (ohne.length) return nein(
        `${ohne.length} von ${p.length} Pflichten ohne Adressaten`,
        'Der Compliance-Agent in BC3-30 muss adressat setzen. Bis dahin gelten '
        + 'sie als bc4 - das kann falsch sein.');
      if (ohneStory) return nein(
        `${ohneStory} Pflicht(en) gelten als baubar, haben aber keine Story`,
        'BC3-40 führt sie unter pflichten_ohne_story. Entweder beim '
        + 'Compliance-Agenten nachfordern oder ausdrücklich als offen liefern.');
      return ja(`Ampel ${a.ampel}, Klasse ${a.ai_act_klasse}`
        + (anhangIII ? `, ${anhangIII}` : '')
        + `. ${p.length} Pflichten zugeordnet: `
        + Object.entries(g).filter(([, v]) => v.length)
            .map(([k, v]) => `${v.length} an ${k}`).join(', '));
    },
  },
  {
    // Seit 22.10.2026 (Restbefund V5): aus "Einstufung gegenprüfen" in BC3-30.
    // Nur gemeldet, Pflicht und Story bleiben in der Lieferung.
    id: 'grundlagen', titel: 'Rechtsgrundlage und Messverfahren der Pflichten',
    pruefen: () => {
      const c = u.compliance || {};
      const art = c.artikel_nur_hochrisiko || [];
      const mv = c.messverfahren_ohne_quelle || [];
      if (!art.length && !mv.length)
        return ja('Artikel passen zur Klasse, Messverfahren ohne Zahlen ohne Quelle');
      return nein(
        [...art.map(x => `Pflicht ${x.pflicht_id} beruft sich auf ${x.artikel} KI-VO, `
          + `der nur bei Hochrisiko gilt (Klasse ${c.ai_act_klasse || 'unbekannt'})`), ...mv].join('; '),
        'Beim Nachbessern die Grundlage richtigstellen (etwa DSGVO Art. 13 für einen Hinweis '
        + 'an Betroffene) und Zahlen ohne Quelle durch "offen: ..." ersetzen. Sonst so freigeben, '
        + 'die Pflicht bleibt inhaltlich bestehen.');
    },
  },
  {
    id: 'ablage', titel: 'Die Lieferung liegt und ist erreichbar',
    pruefen: () => {
      const lief = u.lieferung || {};
      const abgelegt = lief.abgelegt || [];
      const soll = dateien.length;
      if (lief.ablage_gescheitert)
        return nein('die Ablage in Google Drive ist gescheitert - in _vorschau '
          + 'liegt nichts',
          'Der Pull Request ist davon unberührt, er baut aus dem Umschlag. Aber '
          + 'die Stichprobe unten kannst du nicht machen, ohne die Datei zu '
          + 'öffnen. Zugangsdaten für Google Drive in n8n erneuern und BC3-70 '
          + 'einzeln wiederholen.');
      if (!abgelegt.length)
        return nein('keine Dateikennungen im Umschlag',
          'BC3-70 hat sie nicht mitgegeben, oder der Lauf wurde ohne Umschlag '
          + 'gestartet.');
      if (soll && abgelegt.length !== soll)
        return nein(`${abgelegt.length} von ${soll} Dateien abgelegt`,
          'Siehe Protokoll von BC3-70. Der Pull Request enthält trotzdem alle — '
          + 'er baut aus dem Umschlag.');
      return ja(`${abgelegt.length} von ${soll} Dateien in `
        + `_vorschau/${lief.lieferung_id}: ${abgelegt.map(d => d.name).join(', ')}`);
    },
  },
];

const ergebnis = PRUEFUNGEN.map(p => {
  let r;
  try { r = p.pruefen(); }
  catch (e) { r = nein('Die Prüfung selbst ist gescheitert: ' + e.message,
                       'Das ist ein Fehler im Prüfpunkt, nicht in der Lieferung.'); }
  return { id: p.id, titel: p.titel, ...r };
});
const bestaetigt = ergebnis.filter(r => r.ok);
const offen = ergebnis.filter(r => !r.ok);

/**
 * Die Stichprobe - die einzige Frage, die man nicht ohne Hinsehen beantworten
 * kann.
 *
 * Vorher stand hier ein Dropdown "Guete Akzeptanzkriterien: hoch|mittel|gering".
 * Drei Worte zur Auswahl, ohne dass die Kriterien im Formular standen: eine
 * Frage, die man raet. Jetzt stehen drei Kriterien im Wortlaut da, und gefragt
 * ist, welches am wenigsten pruefbar ist.
 *
 * Die Auswahl ist NICHT zufaellig, sondern aus der Lieferungskennung
 * abgeleitet: derselbe Lauf zeigt immer dieselben drei. Sonst waere der
 * Nachweis nicht wiederholbar - und ein Nachweis, den man nicht nachfahren
 * kann, ist keiner.
 */
function streu(text) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
const alleKriterien = alleStories.flatMap(s =>
  (s.akzeptanzkriterien || []).map(a => ({
    story: s.titel,
    text: String(a.text || '').trim(),
    mess: a.messverfahren || null,
  }))).filter(k => k.text);

const saat = streu(String(u.lieferung?.lieferung_id || rein.lauf_id || 'bc3'));
const gezogen = [];
if (alleKriterien.length) {
  const rest = [...alleKriterien];
  for (let i = 0; i < 3 && rest.length; i++) {
    gezogen.push(rest.splice((saat + i * 7919) % rest.length, 1)[0]);
  }
}

/**
 * Die Maschine urteilt, der Mensch prueft.
 *
 * Erste Fassung vom 06.09.2026 zeigte drei Kriterien und fragte: "Welches ist
 * am wenigsten pruefbar?" Das war falsch herum. Svetlanas Einwand am selben
 * Tag: "das ist keine menschliche pruefung, die ich da eintippen muss. es muss
 * ja so laufen: ki erstellt und ich pruefe, mit meinen eigenen worten."
 *
 * Sie hat recht, und es ist auch die richtige Lesart von Artikel 14: Aufsicht
 * heisst uebersteuern koennen, nicht selbst herleiten. Wer die Analyse
 * abverlangt, verlagert die Arbeit statt sie zu pruefen - und bekommt bei der
 * dritten Wiederholung "keine Ahnung", so wie in Lauf 121.
 *
 * Also: die Regeln unten nennen je Kriterium die konkreten Maengel, benennen
 * das schwaechste und sagen warum. Die Gate-2-Seite fragt nur noch, ob das stimmt.
 * Widersprechen ist dabei genauso billig wie zustimmen - ein Klick - damit die
 * Zustimmung nicht der bequemere Weg ist.
 */
const UNBESTIMMT = /\b(schnell|zeitnah|einfach|benutzerfreundlich|angemessen|relevant|zuverl(ä|ae)ssig|korrekt|gut|sinnvoll|effizient|m(ö|oe)glichst|zufriedenstellend)\b/i;
const ZAHL = /\d/;

function woerter(s) {
  return new Set(String(s || '').toLowerCase()
    .replace(/[^a-zäöüß0-9 ]+/g, ' ').split(/\s+/).filter(x => x.length > 4));
}

/**
 * Was ist an diesem Kriterium schwach? Regeln, kein Modell - die Einstufung
 * muss bei jedem Lauf gleich ausfallen und nachlesbar sein.
 */
function maengel(k) {
  const m = [];
  const text = String(k.text || '');
  const mess = String(k.mess || '');

  // Seit 23.10.2026 (Svetlana): ein fehlendes Messverfahren ist kein Einwand mehr. Es kommt so
  // von BC2 und steht als Hinweis auf der Gate-2-Seite. Gewertet wird nur, was BC3 verantwortet.
  if (mess && !/^offen:/i.test(mess)) {
    // Zirkulaer: das Messverfahren wiederholt nur das Kriterium
    const a = woerter(text), b = woerter(mess);
    let gleich = 0;
    for (const x of b) if (a.has(x)) gleich++;
    if (b.size && gleich / b.size > 0.6) {
      m.push({ schwere: 3, was: 'Das Messverfahren wiederholt nur das Kriterium mit '
        + 'denselben Wörtern. Es misst nichts, was nicht schon dasteht.' });
    }
    if (/^\s*(manuelle|händische|haendische)\s+(pruefung|prüfung)/i.test(mess)
        && !ZAHL.test(mess)) {
      m.push({ schwere: 2, was: 'Als Messverfahren steht nur „manuelle Prüfung“ '
        + 'ohne Schwelle oder Stichprobengröße. Zwei Personen kämen zu '
        + 'verschiedenen Ergebnissen.' });
    }
  }

  const u = text.match(UNBESTIMMT);
  if (u) {
    m.push({ schwere: 2, was: `Das Kriterium enthält das unbestimmte Wort „${u[0]}“. Es ist `
      + 'nicht festgelegt, ab wann das zutrifft.' });
  }
  if (!/\bgiven\b|\bgegeben\b/i.test(text) || !/\bthen\b|\bdann\b/i.test(text)) {
    m.push({ schwere: 1, was: 'Kein vollständiges Given/When/Then: Die '
      + 'Ausgangslage oder das erwartete Ergebnis fehlt.' });
  }
  return m.sort((x, y) => y.schwere - x.schwere);
}

const bewertet = gezogen.map(k => ({ ...k, maengel: maengel(k) }));
const punkte = bewertet.map(k => k.maengel.reduce((s, m) => s + m.schwere, 0));
const hoechste = Math.max(...punkte);
// Bei Gleichstand wird das nicht verschwiegen - indexOf haette willkuerlich
// das erste genommen, und eine willkuerliche Auswahl als Urteil auszugeben
// ist schlechter als zu sagen, dass zwei gleich schwach sind.
const gleichAuf = punkte.map((p, i) => p === hoechste && p > 0 ? i : -1)
  .filter(i => i >= 0);
const schwaechstes = gleichAuf.length === 1 ? gleichAuf[0] : -1;

// --- Was nur ein Mensch beurteilen kann -----------------------------------
// Geprüft werden Art. 14 Abs. 4 d und e sowie die Protokollierung nach Art. 12.
const FAEHIGKEITEN = [
  { id: 'uebersteuern', titel: 'Ausgabe übersteuern oder verwerfen',
    muster: /(ü|ue)bersteuer|verwerf|ablehn|korrigier|(ä|ae)nder.*vorschlag|manuell.*eingab/i },
  { id: 'anhalten', titel: 'Betrieb anhalten',
    muster: /anhalt|stopp|abbrech|pausier|aussetz|nicht ausgef(ü|ue)hrt|wartet auf/i },
  { id: 'protokollieren', titel: 'Aufsichtsentscheidung protokollieren (Art. 12)',
    muster: /protokoll|nachvollzieh|audit|festgehalten|dokumentiert|vermerk/i },
];
const aufsicht = FAEHIGKEITEN.map(f => {
  const treffer = alleStories.filter(s =>
    f.muster.test(String(s.titel || '') + ' ' + String(s.beschreibung || '')));
  return { ...f, gedeckt: treffer.length > 0, stories: treffer.map(s => s.titel) };
});
const aufsichtFehlt = aufsicht.filter(f => !f.gedeckt);
const aufsichtStories = alleStories
  .filter(s => FAEHIGKEITEN.some(f => f.muster.test(
    String(s.titel || '') + ' ' + String(s.beschreibung || ''))))
  .map(s => s.titel);
const offenePunkte = dateien.find(x => x._datei === 'offene-punkte');

const menschlich = [
  { id: 'stichprobe', titel: 'Welches der drei Kriterien ist am wenigsten prüfbar?' },
  ...(hochrisiko ? [{ id: 'aufsicht_spezifiziert',
                      titel: 'Sind die Aufsichtsmassnahmen spezifiziert?' }] : []),
];

// --- Der Text, den ein Mensch liest --------------------------------------
//
// Am 06.09.2026 umgeschrieben. Er war zu kryptisch: Marker wie [ok] und ->,
// ASCII-Umlaute ("pruefbar", "Uebersteuern") und Feldnamen statt Saetzen. Das
// hier geht an einen Menschen, der freigeben soll - also liest es sich wie
// etwas, das ein Mensch geschrieben hat.
const z = [];
const kp = u.konzept?.kp_id || '?';
const tp = (u.konzept?.teilprozess_ids || []).join(', ');
const anzEpics = (t.epics || []).length;

z.push(`Freigabe der Lieferung ${u.lieferung?.lieferung_id || rein.lauf_id}`);
z.push('');
z.push(`Es geht um den Kernprozess ${kp}${tp ? ', Teilprozesse ' + tp : ''}. `
  + `Daraus sind ${anzEpics} Epics mit ${alleStories.length} Stories geworden, `
  + `nach Vertrag ${t.schema_version || 'unbekannt'}.`);

const quelleZahlen = t.konzept_ref?.value_quelle;
if (quelleZahlen === 'annahme' || u.konzept?.ist_vorlaeufig === true
    || u.aggregat?.ist_vorlaeufig === true) {
  z.push('Die Zahlen im Konzept sind Annahmen von BC2 und noch nicht belegt. '
    + 'Das färbt alles, was daraus abgeleitet ist.');
} else if (quelleZahlen) {
  z.push(`Die Zahlen im Konzept sind als "${quelleZahlen}" gekennzeichnet.`);
}

if (audit.pruefung_bc3) {
  const weich = (audit.pruefung_bc3.befunde || []).length;
  z.push(`Die Lieferung ist gegen ${audit.pruefung_bc3.geprueft_gegen} geprüft `
    + `worden und hat bestanden`
    + (weich ? `, mit ${weich} weichen Befunden.` : '.'));
} else {
  z.push('Achtung: es liegt kein Prüfergebnis gegen das Ticket-Schema vor. '
    + 'Normalerweise fährt BC3-40 die Lieferung dagegen, bevor irgendetwas '
    + 'hochgeladen wird.');
}

if (offen.length) {
  z.push('');
  z.push(offen.length === 1
    ? 'EIN PUNKT IST OFFEN'
    : `${offen.length} PUNKTE SIND OFFEN`);
  z.push('');
  for (const r of offen) {
    z.push(`${r.titel}: ${r.beleg}`);
    z.push(`Was hilft: ${r.abhilfe}`);
    z.push('');
  }
} else {
  z.push('');
  z.push('Es ist nichts offen. Alles, was sich maschinell prüfen lässt, stimmt.');
}

z.push('');
z.push('DIE AKZEPTANZKRITERIEN — hier brauche ich dein Urteil');
z.push('');
if (bewertet.length) {
  z.push('Ich habe drei Kriterien aus der Lieferung gezogen und durchgesehen. '
    + 'Bei jedem steht, was mir daran auffällt.');
  z.push('');
  bewertet.forEach((k, i) => {
    z.push(`${i + 1}. „${k.text}"`);
    z.push(`   Gehört zur Story: ${k.story}`);
    z.push(`   Gemessen wird das so: ${k.mess || 'Es steht kein Messverfahren dabei.'}`);
    if (k.maengel.length) {
      k.maengel.forEach(m => z.push(`   Mein Einwand: ${m.was}`));
    } else {
      z.push('   Daran habe ich nichts auszusetzen.');
    }
    z.push('');
  });
  if (schwaechstes >= 0) {
    z.push(`Von den dreien halte ich Nummer ${schwaechstes + 1} für das schwächste.`);
  } else if (gleichAuf.length > 1) {
    z.push(`Nummer ${gleichAuf.map(i => i + 1).join(' und ')} sind aus meiner Sicht `
      + 'gleich schwach. Welches schwerer wiegt, kann ich nicht entscheiden.');
  } else {
    z.push('An allen dreien habe ich nichts auszusetzen.');
  }
  z.push('Du musst das nicht selbst herausfinden — sag mir unten nur, ob du es '
    + 'genauso siehst.');
} else {
  z.push('Es gibt keine Kriterien, die ich ziehen könnte. Siehe den offenen '
    + 'Punkt oben.');
}

if (hochrisiko) {
  z.push('');
  z.push('MENSCHLICHE AUFSICHT ÜBER DAS ZIELSYSTEM');
  z.push('');
  z.push('Diese Lieferung fällt unter Hochrisiko. Erkannt habe ich das über: '
    + hochrisikoQuelle + '.');
  z.push('');
  z.push('Art. 14 Abs. 4 KI-VO verlangt unter anderem, dass Menschen die Ausgabe '
    + 'übersteuern oder verwerfen (Buchst. d) und den Betrieb anhalten können '
    + '(Buchst. e). Dazu kommt die Protokollierung nach Art. 12. Ob die Lieferung '
    + 'diese drei beschreibt, habe ich nachgesehen:');
  z.push('');
  aufsicht.forEach(f => {
    z.push(f.gedeckt
      ? `Ja — ${f.titel}. Abgedeckt durch: ${f.stories.slice(0, 2).join('; ')}`
      : `Nein — ${f.titel}. Dazu habe ich keine Story gefunden.`);
  });
  z.push('');
  z.push(aufsichtFehlt.length
    ? 'Damit halte ich diesen Punkt für nicht erfüllt. Es fehlt: '
      + (aufsichtFehlt.length === 1 ? aufsichtFehlt[0].titel
         : aufsichtFehlt.slice(0, -1).map(f => f.titel).join(', ')
           + ' und ' + aufsichtFehlt.at(-1).titel) + '.'
    : 'Damit halte ich diesen Punkt für erfüllt: alle drei sind belegt.');
  z.push('Auch hier: du musst es nicht selbst suchen, nur bestätigen oder '
    + 'widersprechen.');
}

z.push('');
z.push('ZUR KENNTNIS — dazu brauche ich keine Antwort');
z.push('');
z.push('Schnittstellen erzeugt dieser Lauf nicht (API-Teil von BC3-50 abgeschaltet).');
if (offenePunkte) {
  z.push(`Offen sind insgesamt ${offenePunkte.anzahl} Punkte: `
    + Object.entries(offenePunkte.nach_adressat || {})
        .map(([a, n]) => `${n} für ${a}`).join(', ')
    + '. Die Liste bleibt bei uns in _vorschau, im Pull Request steht nur die Anzahl.');
}

z.push('');
z.push(bestaetigt.length === ergebnis.length
  ? `Maschinell geprüft habe ich ${ergebnis.length} Punkte, alle in Ordnung:`
  : `Maschinell geprüft habe ich ${ergebnis.length} Punkte, davon `
    + `${bestaetigt.length} in Ordnung:`);
z.push('');
for (const r of bestaetigt) z.push(`${r.titel} — ${r.beleg}`);

z.push('');
z.push('WAS PASSIERT, WENN DU ENTSCHEIDEST');
z.push('');
z.push('Freigeben legt einen Zweig im Repo an, öffnet einen Pull Request und führt '
  + 'ihn zusammen; BC4 holt die Lieferung aus main. Nachbessern und Ablehnen tun '
  + 'das nicht — der Lauf endet, die Dateien bleiben in _vorschau liegen, und '
  + 'beides wird in der Tabelle freigaben festgehalten.');
z.push('');
z.push('Zum Schluss etwas Unangenehmes, das dazugehört: du hast diese Lieferung '
  + 'erstellt und gibst sie auch frei. Das Namensfeld unten ist nicht geprüft '
  + 'und belegt keine Vier-Augen-Kontrolle. BC3 führt den Pull Request selbst '
  + 'zusammen, eine zweite Prüfung durch BC4 findet vorher nicht statt.');

return [{
  json: {
    ...rein,
    uebersicht: z.join('\n'),
    pruefung: {
      geprueft: ergebnis,
      bestaetigt: bestaetigt.map(r => r.id),
      offen: offen.map(r => r.id),
      menschlich: menschlich.map(p => p.id),
      hochrisiko,
      hochrisiko_quelle: hochrisikoQuelle,
      stichprobe: bewertet,
      stichprobe_schwaechstes: schwaechstes >= 0 ? schwaechstes + 1 : null,
      stichprobe_gleichauf: gleichAuf.map(i => i + 1),
      aufsicht: aufsicht.map(f => ({ id: f.id, gedeckt: f.gedeckt })),
      aufsicht_urteil: aufsichtFehlt.length ? 'nicht erfuellt' : 'erfuellt',
      stand: `${bestaetigt.length} von ${ergebnis.length} maschinell bestätigt`,
    },
    tickets: t,
  },
}];

/**
 * Abdeckungstabelle fuer Gate 2 (seit 11.10.2026, ueberarbeitet 12.10.2026).
 *
 * BC3-20 laesst jede Story angeben, welche Anforderungen (A..), Kriterien
 * (K..) von BC2 und Vorgaben von BC3 (V..) sie abdeckt (deckt_ab), und prueft,
 * dass keine Nummer fehlt. Das beweist nur, dass das Modell die Nummer NENNT.
 * Ob die Story sie auch enthaelt, kann nur ein Mensch beurteilen - deshalb
 * steht hier je Nummer der Wortlaut neben der Story, die sie beansprucht.
 *
 * Die Hinweise sind Regeln ohne Sprachmodell und ersetzen das Hinsehen nicht:
 * - Anteil der Begriffe aus der Vorgabe, die in der Story wiederkommen. Seit
 *   12.10.2026 ueber Wortteile (Dreiergruppen), damit "Quellverweis" und
 *   "Quellenverweisen" als gleich zaehlen.
 * - Bei K-Nummern das am besten passende Kriterium statt des ersten.
 * - "passt besser zu": eine Story, die die Nummer NICHT beansprucht, enthaelt
 *   deutlich mehr davon.
 * - Eine Story beansprucht mehr Vorgaben (V), als sie Kriterien hat.
 * - Zwei Stories sind fast gleich (Dublette, etwa nach dem zweiten Durchgang).
 *
 * Seit 12.10.2026 steht hier auch der Hinweis TESTLAUF, solange
 * umschlag.lauf.liefermodus nicht 'echt' ist: dann legt eine Freigabe keinen
 * Pull Request im Gruppen-Repository an.
 */
const rein = $input.first().json;
const u = rein.umschlag || {};
const potenziale = u.potenziale || [];
const agg = u.aggregat || {};
const epics = agg.epics || u.epics || [];
const vorgabenJeEpic = agg.vorgaben_je_epic || [];

const test = (u.lauf?.liefermodus || 'test') !== 'echt';
const BANNER = test
  ? 'TESTLAUF – "Freigeben" legt KEINEN Pull Request im Gruppen-Repository an. '
    + 'Echt geliefert wird erst, wenn in BC3-00 "Lauf einstellen" liefermodus auf echt steht.\n\n'
  : '';

// --- Vergleich ueber Wortteile ---------------------------------------------
const FUELL = new Set(['eine', 'einer', 'einem', 'einen', 'eines', 'wird', 'werden', 'wurde', 'nicht',
  'oder', 'sowie', 'dass', 'wenn', 'dann', 'sind', 'ihre', 'ihren', 'alle', 'allen', 'mehr', 'nach',
  'ueber', 'über', 'durch', 'beim', 'given', 'when', 'then', 'gegeben', 'diese', 'dieser', 'dieses',
  'kann', 'muss', 'soll', 'damit', 'auch', 'noch', 'sich', 'etwa', 'jede', 'jeder', 'jedes', 'mindestens',
  'system', 'systems', 'story']);
const woerter = s => [...new Set(String(s || '').toLowerCase()
  .replace(/ß/g, 'ss')
  .replace(/[^a-zäöü0-9 ]+/g, ' ').split(/\s+/)
  .filter(x => x.length > 3 && !FUELL.has(x)))];
const dreier = w => { const s = ` ${w} `; const g = new Set(); for (let i = 0; i < s.length - 2; i++) g.add(s.slice(i, i + 3)); return g; };
const DREIER = new Map();
const dreierVon = w => { if (!DREIER.has(w)) DREIER.set(w, dreier(w)); return DREIER.get(w); };
function wortGleich(a, b) {
  if (a === b) return true;
  if (Math.min(a.length, b.length) >= 5 && (a.startsWith(b) || b.startsWith(a))) return true;
  // Wortende (seit 13.10.2026): Zusammensetzungen wie 'Vorschlagsliste' / 'Liste'.
  if (Math.min(a.length, b.length) >= 5 && (a.endsWith(b) || b.endsWith(a))) return true;
  const A = dreierVon(a), B = dreierVon(b);
  let g = 0; for (const x of A) if (B.has(x)) g++;
  return (2 * g) / (A.size + B.size) >= 0.6;
}
/** Anteil der Begriffe aus quelle, die in ziel wiederkommen (0..1). */
function anteil(quelle, ziel) {
  const q = woerter(quelle), z = woerter(ziel);
  if (!q.length) return 1;
  let treffer = 0;
  for (const w of q) if (z.some(x => wortGleich(w, x))) treffer++;
  return treffer / q.length;
}

const text = t => typeof t === 'string' ? t
  : [t?.kriterium, t?.messverfahren ? `Messverfahren: ${t.messverfahren}` : null].filter(Boolean).join(' ');
const kurz = (s, n) => {
  s = String(s || '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
};
const storyText = s => [s.titel, s.beschreibung,
  ...(s.akzeptanzkriterien || []).map(k => `${k.text || ''} ${k.messverfahren || ''}`)].join(' ');
const prozent = x => Math.round(x * 100);

const ZWEIFEL = 0.35;     // darunter: "Bitte pruefen"
const BESSER = 0.2;       // so viel naeher muss eine fremde Story sein

const zeilen = [];
const tabelle = [];
const hinweiseStories = [];
let zweifel = 0;
let fehlt = 0;

epics.forEach((e, i) => {
  const p = potenziale[i] || {};
  const soll = [
    ...(p.fachliche_anforderungen || []).map((x, n) => ({ nr: `A${n + 1}`, quelle: 'BC2', text: text(x), mess: null })),
    ...(p.akzeptanzkriterien_geschaeftlich || []).map((x, n) => ({ nr: `K${n + 1}`, quelle: 'BC2',
      text: typeof x === 'string' ? x : String(x?.kriterium || ''), mess: typeof x === 'string' ? null : (x?.messverfahren || null) })),
    ...(vorgabenJeEpic[i] || []).map(v => ({ nr: v.nr, quelle: 'BC3', text: v.text, mess: null })),
  ];
  if (!soll.length) return;
  const stories = e.stories || [];
  const anspruch = s => (s.deckt_ab || []).map(x => String(x).trim().toUpperCase());
  zeilen.push(`Epic ${i + 1}: ${e.titel || ''}`);
  zeilen.push('');

  for (const v of soll) {
    const voll = v.mess ? `${v.text} Messverfahren: ${v.mess}` : v.text;
    const beansprucht = stories.filter(s => anspruch(s).includes(v.nr));
    const bewertet = beansprucht.map(s => {
      // Bei K: das einzelne Kriterium, das am besten passt
      const kriterien = s.akzeptanzkriterien || [];
      let bestK = null, bestKw = -1;
      for (const k of kriterien) {
        const w = anteil(voll, `${k.text || ''} ${k.messverfahren || ''}`);
        if (w > bestKw) { bestKw = w; bestK = k; }
      }
      return { s, gesamt: anteil(voll, storyText(s)), kriterium: bestK,
               mess: v.mess && bestK ? anteil(v.mess, bestK.messverfahren || '') : null };
    });
    const best = bewertet.reduce((m, x) => Math.max(m, x.gesamt), 0);
    const fremd = stories.filter(s => !anspruch(s).includes(v.nr))
      .map(s => ({ s, gesamt: anteil(voll, storyText(s)) }))
      .sort((a, b) => b.gesamt - a.gesamt)[0];
    const naeher = fremd && fremd.gesamt >= ZWEIFEL && fremd.gesamt - best >= BESSER ? fremd : null;

    const status = !beansprucht.length ? 'fehlt' : (best < ZWEIFEL ? 'zweifelhaft' : 'ok');
    if (status === 'fehlt') fehlt++;
    if (status === 'zweifelhaft') zweifel++;
    tabelle.push({ epic: i + 1, nummer: v.nr, quelle: v.quelle, text: v.text, status,
      anteil: prozent(best), naeher_an: naeher ? naeher.s.titel : null,
      stories: bewertet.map(x => ({ titel: x.s.titel, anteil: prozent(x.gesamt),
        kriterium: x.kriterium?.text || '', messverfahren_anteil: x.mess == null ? null : prozent(x.mess) })) });

    zeilen.push(`${v.nr}${v.quelle === 'BC3' ? ' (Vorgabe BC3)' : ''} – „${kurz(voll, 220)}“`);
    if (!beansprucht.length) zeilen.push('   Keine Story nennt diese Nummer.');
    bewertet.forEach(x => zeilen.push(
      `   → ${x.s.titel}: „${kurz(x.kriterium?.text || '', 170)}“ (${prozent(x.gesamt)} % der Begriffe wiedergefunden)`));
    if (status === 'zweifelhaft') zeilen.push('   Bitte prüfen: wenig davon steht in der Story, die Zuordnung könnte nur behauptet sein.');
    if (naeher) zeilen.push(`   Passt besser zu „${naeher.s.titel}“ (${prozent(naeher.gesamt)} %), die diese Nummer nicht beansprucht.`);
    const gekuerzt = bewertet.filter(x => x.mess != null && x.mess < 0.3);
    if (v.mess && gekuerzt.length && gekuerzt.length === bewertet.length) {
      zeilen.push('   Das Messverfahren von BC2 ist in keinem Kriterium wiederzuerkennen – gekürzt oder ersetzt?');
    }
    zeilen.push('');
  }

  // Stories, die mehr Vorgaben beanspruchen, als sie Kriterien haben
  for (const s of stories) {
    const v = anspruch(s).filter(x => x.startsWith('V')).length;
    const k = (s.akzeptanzkriterien || []).length;
    if (v > 1 && v > k) {
      hinweiseStories.push(`Epic ${i + 1}, „${s.titel}“ beansprucht ${v} Vorgaben von BC3, hat aber nur ${k} Kriterium/Kriterien. Jede Vorgabe sollte ein eigenes Kriterium haben.`);
    }
  }
  // Dubletten
  for (let a = 0; a < stories.length; a++) {
    for (let b = a + 1; b < stories.length; b++) {
      const x = anteil(storyText(stories[a]), storyText(stories[b]));
      const y = anteil(storyText(stories[b]), storyText(stories[a]));
      if (Math.min(x, y) >= 0.6) {
        hinweiseStories.push(`Epic ${i + 1}: „${stories[a].titel}“ und „${stories[b].titel}“ sind fast gleich (${prozent(Math.min(x, y))} %) – mögliche Dublette.`);
      }
    }
  }
});

// --- Sprachmodelle des Laufs (seit 12.10.2026) ------------------------------
// Jede KI-Stufe schreibt ihr Modell ins Protokoll (Feld modelle). Regel fuer
// BC3: Mistral mit fester Version; OpenAI ist nur fuer Tests zugelassen.
const modelle = (u.protokoll || []).flatMap(p => (p.modelle || []).map(m => ({ stufe: p.stufe, ...m })));
const regelGerecht = m => /mistral|ministral|codestral|pixtral/i.test(m.modell) && !/latest/i.test(m.modell);
const abweichend = modelle.filter(m => !regelGerecht(m));
const modellBlock = modelle.length
  ? ['SPRACHMODELLE IN DIESEM LAUF', '',
     ...modelle.map(m => `${m.schritt}: ${m.modell}${regelGerecht(m) ? '' : ' – nicht nach der Modellregel von BC3 (Mistral, feste Version)'}`),
     ...(abweichend.length
       ? [test
           ? 'Das ist für Testläufe zugelassen. Vor einer echten Lieferung auf Mistral mit fester Version umstellen.'
           : 'ACHTUNG: echter Lauf mit Modellen außerhalb der Regel. Vor der Freigabe auf Mistral mit fester Version umstellen.']
       : []),
     '']
  : [];

// Absatz "WAS PASSIERT, WENN DU ENTSCHEIDEST" aus 'Gate 2 vorbereiten' gilt nur
// fuer echte Laeufe. Im Testmodus widersprach er dem Banner oben (Lauf 419).
const ABSATZ_ECHT = 'Freigeben legt einen Zweig im Repo an, öffnet einen Pull Request und führt '
  + 'ihn zusammen; BC4 holt die Lieferung aus main. Nachbessern und Ablehnen tun '
  + 'das nicht — der Lauf endet, die Dateien bleiben in _vorschau liegen, und '
  + 'beides wird in der Tabelle freigaben festgehalten.';
const ABSATZ_TEST = 'TESTLAUF: Auch Freigeben legt keinen Zweig und keinen Pull Request an. '
  + 'Bei jeder Entscheidung endet der Lauf, '
  + 'die Dateien bleiben in _vorschau liegen, und die Entscheidung wird festgehalten.';
const ueb = String(rein.uebersicht || '');

// --- Worauf die Einstufung beruht (seit 13.10.2026) -------------------------
// Lauf 438: UC2 wurde Hochrisiko, ohne dass Gate 2 sagte, warum. Jetzt stehen
// die Begruendung des Compliance-Agenten und die Belegsaetze der Regeln aus
// BC3-20 (Tragweite) hier, damit ein Mensch die Einstufung pruefen kann.
const tw = agg.tragweite || {};
const comp = u.compliance || {};
const twErkannt = tw.erkannt || [];
const twUnsicher = tw.zu_pruefen || [];
const einst = [];
if (comp.ai_act_klasse === 'high' || twErkannt.length || twUnsicher.length) {
  einst.push('WORAUF DIE EINSTUFUNG BERUHT', '');
  einst.push(`Compliance-Agent: Klasse ${comp.ai_act_klasse || 'unbekannt'}`
    + `${comp.anhang_iii_kategorie ? ', ' + comp.anhang_iii_kategorie : ''}. `
    + `Begründung: ${comp.begruendung_ampel || 'keine angegeben'}`);
  for (const x of twErkannt) einst.push(`Regel, eindeutig: ${x.art} (${x.anhang}) – „${x.beleg}“`);
  for (const x of twUnsicher) einst.push(`Regel, nur Stichwort – bitte prüfen: ${x.art} (${x.anhang}) – „${x.beleg}“`);
  if (comp.ai_act_klasse === 'high' && !twErkannt.length) {
    einst.push('ACHTUNG: Der Compliance-Agent stuft als Hochrisiko ein, die Regeln finden aber keine '
      + 'eindeutige Entscheidung über Personen. Bitte prüfen, ob die Einstufung stimmt.');
  }
  if (comp.ai_act_klasse !== 'high' && twErkannt.length) {
    einst.push('ACHTUNG: Die Regeln finden eine Entscheidung über Personen, der Compliance-Agent '
      + 'stuft aber nicht als Hochrisiko ein. Bitte prüfen.');
  }
  // Seit 13.10.2026: Hochrisiko ist baubar mit Auflagen (BC3-30 'Umschlag ergaenzen').
  const auf = comp.auflagen_hochrisiko;
  if (auf) {
    einst.push('', 'BAUBAR MIT AUFLAGEN',
      `Von BC3 als Story ergänzt: ${(auf.art14_ergaenzt || []).join('; ') || 'nichts, die drei Fähigkeiten nach Art. 14 waren schon da'}.`,
      `Unterlagen für den Betrieb, als Vorlage in compliance-audit.json (Pflichten u-…, an die Organisation): ${(auf.unterlagen || []).join('; ')}.`,
      auf.hinweis || '');
  }
  einst.push('');
}
const mitEinstufung = t => {
  if (!einst.length) return t;
  const block = einst.join('\n');
  for (const anker of ['\nMENSCHLICHE AUFSICHT', '\nZUR KENNTNIS']) {
    if (t.includes(anker)) return t.replace(anker, '\n' + block + anker);
  }
  return t + '\n\n' + block;
};
const basis = BANNER + mitEinstufung(test ? ueb.replace(ABSATZ_ECHT, ABSATZ_TEST) : ueb);

if (!tabelle.length) {
  const nurModelle = modellBlock.length
    ? (basis.includes('\nZUR KENNTNIS')
        ? basis.replace('\nZUR KENNTNIS', '\n\n' + modellBlock.join('\n') + '\nZUR KENNTNIS')
        : basis + '\n\n' + modellBlock.join('\n'))
    : basis;
  return [{ json: { ...rein, uebersicht: nurModelle, liefermodus: test ? 'test' : 'echt', abdeckung: [],
    pruefung: { ...(rein.pruefung || {}), modelle, modelle_ausserhalb_regel: abweichend.length } } }];
}

const kopf = [
  '',
  'ABDECKUNG DER VORGABEN – bitte überfliegen',
  '',
  'Je Anforderung (A) und Akzeptanzkriterium (K) von BC2 und je Vorgabe von BC3 (V) steht hier die Story, '
  + 'die sie abdecken soll, mit dem Anteil der Begriffe, die dort wiederkommen. '
  + (zweifel || fehlt || hinweiseStories.length
    ? `${zweifel} Zuordnung(en) sind zweifelhaft${fehlt ? `, ${fehlt} fehlen ganz` : ''}`
      + `${hinweiseStories.length ? `, dazu ${hinweiseStories.length} Hinweis(e) zu einzelnen Stories` : ''}.`
    : 'Keine Zuordnung fällt auf, ein kurzer Blick genügt.'),
  '',
];
const fuss = hinweiseStories.length
  ? ['ZU EINZELNEN STORIES', '', ...hinweiseStories, '']
  : [];

const anker = '\nZUR KENNTNIS';
const block = [...kopf, ...zeilen, ...fuss, ...modellBlock].join('\n');
const neu = basis.includes(anker)
  ? basis.replace(anker, '\n' + block + anker)
  : basis + '\n' + block;

return [{
  json: {
    ...rein,
    uebersicht: neu,
    liefermodus: test ? 'test' : 'echt',
    pruefung: {
      ...(rein.pruefung || {}),
      abdeckung: { nummern: tabelle.length, zweifelhaft: zweifel, fehlt, hinweise_stories: hinweiseStories.length },
      modelle,
      modelle_ausserhalb_regel: abweichend.length,
    },
    abdeckung: tabelle,
    abdeckung_hinweise: hinweiseStories,
  },
}];

// Baut die Daten der Gate-2-Seite aus dem Lauf (wie werkzeug\daten-bauen.py) und die Adresse,
// über die BC3-81 den wartenden Lauf weckt. Speichert nichts, das macht "Gate-2-Daten speichern".
const j = $input.first().json;
const u = j.umschlag || {};
const p = j.pruefung || {};
const t = j.tickets || {};
const lief = u.lieferung || {};
const lauf_id = (u.lauf || {}).lauf_nr;
const resume_url = $execution.resumeUrl;
if (!lauf_id) throw new Error('Gate-2-Daten bauen: Laufnummer fehlt in umschlag.lauf.lauf_nr');
if (!resume_url) throw new Error('Gate-2-Daten bauen: $execution.resumeUrl fehlt, BC3-81 könnte den Lauf nicht wecken');

// Belege für die drei Fähigkeiten nach Art. 14 Abs. 4 und Art. 12 (Suchwörter wie in "Gate 2 vorbereiten")
const FAEHIGKEITEN = [
  ['uebersteuern', 'Ausgabe übersteuern oder verwerfen (Art. 14 Abs. 4 d)',
    /(ü|ue)bersteuer|verwerf|ablehn|korrigier|(ä|ae)nder.*vorschlag|manuell.*eingab/i],
  ['anhalten', 'Betrieb anhalten (Art. 14 Abs. 4 e)',
    /anhalt|stopp|abbrech|pausier|aussetz|nicht ausgef(ü|ue)hrt|wartet auf/i],
  ['protokollieren', 'Aufsichtsentscheidung protokollieren (Art. 12)',
    /protokoll|nachvollzieh|audit|festgehalten|dokumentiert|vermerk/i],
];
const epics = t.epics || [];
const stories = epics.flatMap(e => e.stories || []);
const aufsicht = FAEHIGKEITEN.map(([id, titel, muster]) => ({
  id, titel,
  stories: stories.filter(s => muster.test(`${s.titel || ''} ${s.beschreibung || ''}`)).map(s => s.titel).slice(0, 3),
}));

const audit = (lief.dateien || []).find(x => String(x._datei || '').startsWith('compliance')) || {};
const pb = audit.pruefung_bc3 || {};
const comp = u.compliance || {};
const konzept = u.konzept || {};
// Gegenprobe aus BC3-30: Fundstelle unbekannt oder "high" ohne Treffer der Regeln
const strittig = comp.einstufung_strittig || [];

const kurz = (s, n) => { const x = String(s ?? ''); return x.length > n ? x.slice(0, n - 1) + '…' : x; };

// Was von BC2 kam: Konzept, Gate 1, Potenziale mit Anzahl der Nummern (A, K, V)
function eingangVon(u) {
  const k = u.konzept || {}, q = u.quelle || {}, g1 = k.gate1 || {};
  // Link auf die Datei bei GitHub statt auf die Rohfassung
  const m = String(q.url || '').match(/^https:\/\/raw\.githubusercontent\.com\/([^/]+\/[^/]+)\/([^/]+)\/(.+)$/);
  return {
    unternehmen: k.unternehmen || null,
    konzept_id: k.konzept_id || null,
    paket_id: (u.ids || {}).paket_id || null,
    quelle: q.pfad || (u.lauf || {}).pfad || null,
    quelle_link: m ? `https://github.com/${m[1]}/blob/${m[2]}/${m[3]}` : null,
    gate1: g1.status || null,
    gate1_befunde: (g1.befunde || []).map(b => kurz(b, 200)),
    vorlaeufig: k.ist_vorlaeufig === true,
    prozess: kurz(k.prozess, 400),
    potenziale: (u.potenziale || []).map(x => ({ titel: x.use_case_titel, rang: x.rang ?? null,
      a: (x.fachliche_anforderungen || []).length, k: (x.akzeptanzkriterien_geschaeftlich || []).length,
      v: (x.bc3_vorgaben || []).length })),
  };
}

// Was im Lauf passiert ist: je Schritt Stand, Modell und Befunde (aus dem Protokoll)
function schritteVon(u) {
  return (u.protokoll || []).filter(x => x.status !== 'gestartet').map(x => ({
    stufe: x.stufe, status: x.status, zeitpunkt: x.zeitpunkt || null,
    modelle: [...new Set((x.modelle || []).map(m => m.modell).filter(Boolean))],
    // Seit 23.10.2026: 20 statt 8, BC3-40 meldet je Zuordnung aus abgedeckt_durch einen Prüfen-Befund (C9)
    befunde: (x.befunde || []).slice(0, 20).map(b => kurz(b, 300)),
    weitere: Math.max(0, (x.befunde || []).length - 20),
  }));
}

// Was rausgeht: abgelegte Dateien mit Link und was die Freigabe auslöst
function ausgangVon(u, lief) {
  const echt = (u.lauf || {}).liefermodus === 'echt';
  return {
    ordner_link: lief.ordner ? `https://drive.google.com/drive/folders/${lief.ordner}` : null,
    dateien: (lief.abgelegt || []).map(d => ({ name: d.name, link: d.id ? `https://drive.google.com/file/d/${d.id}/view` : null })),
    offene_punkte: u.offene_punkte || null,
    bei_freigabe: echt
      ? 'Freigeben legt einen Zweig in pg-coe-kmu/coe-factory an, öffnet einen Pull Request und führt ihn zusammen. BC4 holt die Lieferung aus main. Die Entscheidung steht in der Tabelle freigaben.'
      : 'Testlauf: Freigeben hält nur die Entscheidung in der Tabelle freigaben fest. Es entsteht kein Pull Request, BC4 bekommt nichts.',
  };
}

const daten = {
  ausfuehrung: String($execution.id),
  lauf_nr: lauf_id,
  liefermodus: (u.lauf || {}).liefermodus,
  lieferung_id: lief.lieferung_id,
  kp_id: konzept.kp_id,
  teilprozesse: konzept.teilprozess_ids || [],
  schema_version: t.schema_version,
  value_quelle: (t.konzept_ref || {}).value_quelle,
  pruefung_bc3: { geprueft_gegen: pb.geprueft_gegen, ergebnis: pb.ergebnis, befunde: pb.befunde },
  geprueft: p.geprueft || [],
  hochrisiko: p.hochrisiko,
  hochrisiko_quelle: p.hochrisiko_quelle + (strittig.length ? ' – strittig: ' + strittig.join('; ') : ''),
  stichprobe: (p.stichprobe || []).map(k => ({ story: k.story, text: k.text, mess: k.mess,
    maengel: (k.maengel || []).map(m => m.was) })),
  stichprobe_schwaechstes: p.stichprobe_schwaechstes,
  stichprobe_gleichauf: p.stichprobe_gleichauf || [],
  aufsicht,
  einstufung: { ampel: comp.ampel, ai_act_klasse: comp.ai_act_klasse,
    anhang_iii_kategorie: comp.anhang_iii_kategorie, begruendung_ampel: comp.begruendung_ampel,
    strittig },
  auflagen: comp.auflagen_hochrisiko || null,
  abdeckung: j.abdeckung || [],
  abdeckung_hinweise: j.abdeckung_hinweise || [],
  modelle: p.modelle || [],
  offene_punkte: u.offene_punkte,
  ablage_gescheitert: lief.ablage_gescheitert,
  epics: epics.map(e => ({ titel: e.titel, ziel: e.ziel, kategorien: e.kategorien || [],
    stories: (e.stories || []).map(s => ({ id: s.story_id, titel: s.titel, beschreibung: s.beschreibung,
      kriterien: s.akzeptanzkriterien || [] })) })),
  // Seit 22.10.2026 (Expertenrunde Gate 2): die Seite zeigt wie ein Lieferschein,
  // was reinkam, was im Lauf passiert ist und was rausgeht
  eingang: eingangVon(u),
  schritte: schritteVon(u),
  regeln: ((u.plan || {}).regeln || []).map(r => ({ regel: r.regel, greift: !!r.greift, begruendung: kurz(r.begruendung, 200) })),
  pflichten: (comp.pflichten || []).slice(0, 40).map(p => ({ tag: p.tag, text: kurz(p.text, 300),
    massnahme: p.massnahme, adressat: p.adressat, stelle: kurz(p.stelle, 120) })),
  ausgang: ausgangVon(u, lief),
};

// Text für Telegram: nur Kennungen und Zahlen, keine Inhalte (Server außerhalb der EU)
const FRIST_TAGE = 7;
const frist = new Date(Date.now() + FRIST_TAGE * 864e5).toLocaleString('de-DE',
  { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const offen = (p.geprueft || []).filter(g => !g.ok).length;
const nachricht = `Gate 2 wartet: ${lauf_id}${daten.liefermodus === 'echt' ? '' : ' (Test)'}, `
  + `${konzept.kp_id || 'ohne KP'}, ${epics.length} Epics, ${stories.length} Stories, `
  + `${offen} offene${offen === 1 ? 'r Punkt' : ' Punkte'}, Hochrisiko ${p.hochrisiko ? (strittig.length ? 'strittig' : 'ja') : 'nein'}. Frist ${frist}.`;

return [{ json: { lauf_id, resume_url, daten, nachricht } }];
